60	export function setUserEmail(email: string) {
61	  const globalConfig = readGlobalConfig();
62	  const account = globalConfig?.account ?? {};
63	  account.email = email;
64	  const config: Partial<GlobalConfig> = { account };
65	  writeGlobalConfigPartial(config);
66	}
