153	    };
154	  }
155	
156	  if (ciMode) {
157	    // CI uses a synthetic placeholder to avoid interactive prompts. Treat it as
158	    // already validated so test runs do not depend on live account state.
159	    return {
160	      status: EmailValidationStatus.OK,
161	      hasEmail: true,
162	      email: userEmail,
163	    };
164	  }
165	
166	  try {
167	    const validateParam = options?.validate ? '&validate=true' : '';
168	    // Use longer timeout when validation is requested
169	    const timeout = options?.validate ? 3000 : 500;
170	
171	    // Log when we're validating the email since it can take a sec
172	    if (options?.validate) {
173	      logger.info(`Checking email...`);
174	    }
175	
176	    const host = getEnvString('PROMPTFOO_CLOUD_API_URL', 'https://api.promptfoo.app');
